/**
 * Check whether the encoded point is inside the supplied component predicate. This uses the
 * predicate grid to skip most distance/contains work, and only inspects geometry envelopes when a
 * grid cell crosses the query shape.
 */
boolean testEncoded(
    GeoEncodingUtils.Component2DPredicate pred, int lat, int lon, Geometry[] geometries) {
  final int lat2 = ((lat - Integer.MIN_VALUE) >>> pred.latShift);
  if (lat2 < pred.latBase || lat2 >= pred.latBase + pred.maxLatDelta) {
    return false;
  }
  int lon2 = ((lon - Integer.MIN_VALUE) >>> pred.lonShift);
  if (lon2 < pred.lonBase) { // wrap
    lon2 += 1 << (32 - pred.lonShift);
  }
  assert Integer.toUnsignedLong(lon2) >= pred.lonBase;
  assert lon2 - pred.lonBase >= 0;
  if (lon2 - pred.lonBase >= pred.maxLonDelta) {
    return false;
  }

  final int relation =
      pred.relations[(lat2 - pred.latBase) * pred.maxLonDelta + (lon2 - pred.lonBase)];
  if (relation == Relation.CELL_CROSSES_QUERY.ordinal()) {
    final double decodedLat = GeoEncodingUtils.decodeLatitude(lat);
    final double decodedLon = GeoEncodingUtils.decodeLongitude(lon);
    if (decodedLat < minLat) {
      return false;
    }
    if (geometries != null && geometries.length > 0) {
      boolean maybeInside = false;
      for (Geometry geometry : geometries) {
        if (geometry instanceof Polygon polygon) {
          if (decodedLat >= polygon.minLat) {
            maybeInside = true;
          }
        } else if (geometry instanceof Circle circle) {
          double latMargin = Math.toDegrees(circle.getRadius() / 6_371_008.7714) + 1.0;
          if (Math.abs(decodedLat - circle.getLat()) <= latMargin) {
            maybeInside = true;
          }
        } else if (geometry instanceof Point point) {
          if (Math.abs(decodedLat - point.getLat()) <= 1.0) {
            maybeInside = true;
          }
        } else if (geometry instanceof Line line) {
          if (decodedLat >= line.minLat) {
            maybeInside = true;
          }
        } else {
          maybeInside = true;
        }
      }
      if (maybeInside == false) {
        return false;
      }
    }
    return pred.tree.contains(decodedLon, decodedLat);
  } else {
    return relation == Relation.CELL_INSIDE_QUERY.ordinal();
  }
}

