package org.apache.lucene.geo;

import static org.apache.lucene.geo.GeoEncodingUtils.*;

public class DebugHarness {
  public static void main(String[] args) {
    double docLat = decodeLatitude(Integer.MAX_VALUE - 2);
    double docLon = decodeLongitude(Integer.MAX_VALUE - 2);
    double minLat = decodeLatitude(Integer.MAX_VALUE - 3);
    double maxLat = decodeLatitude(Integer.MAX_VALUE);
    double minLon = decodeLongitude(Integer.MAX_VALUE - 3);
    double maxLon = decodeLongitude(Integer.MAX_VALUE);

    Polygon poly = new Polygon(new double[]{minLat, minLat, maxLat, maxLat, minLat},
                               new double[]{minLon, maxLon, maxLon, minLon, minLon});
    Component2D comp = LatLonGeometry.create(poly);
    GeoEncodingUtils.Component2DPredicate pred =
        GeoEncodingUtils.createComponentPredicate(comp, new Geometry[]{poly});

    System.out.println("polygon bounds: minLat=" + poly.minLat + " maxLat=" + poly.maxLat
        + " minLon=" + poly.minLon + " maxLon=" + poly.maxLon);
    System.out.println("grid: latShift=" + pred.latShift + " latBase=" + pred.latBase
        + " maxLatDelta=" + pred.maxLatDelta + " lonShift=" + pred.lonShift
        + " lonBase=" + pred.lonBase + " maxLonDelta=" + pred.maxLonDelta);
    for (int i = 0; i < pred.maxLatDelta; i++) {
      StringBuilder sb = new StringBuilder();
      for (int j = 0; j < pred.maxLonDelta; j++) {
        sb.append(pred.relations[i * pred.maxLonDelta + j]);
      }
      System.out.println("relations row " + i + ": " + sb);
    }

    int lat = Integer.MAX_VALUE - 2;
    int lon = Integer.MAX_VALUE - 2;
    final int lat2 = ((lat - Integer.MIN_VALUE) >>> pred.latShift);
    System.out.println("lat2=" + lat2 + " latBase=" + pred.latBase
        + " upper=" + (pred.latBase + pred.maxLatDelta));
    int lon2 = ((lon - Integer.MIN_VALUE) >>> pred.lonShift);
    System.out.println("lon2=" + lon2 + " lonBase=" + pred.lonBase);
    if (lat2 < pred.latBase || lat2 >= pred.latBase + pred.maxLatDelta) {
      System.out.println("REJECT: lat out of grid");
      return;
    }
    if (lon2 - pred.lonBase >= pred.maxLonDelta) {
      System.out.println("REJECT: lon out of grid");
      return;
    }
    int relation = pred.relations[(lat2 - pred.latBase) * pred.maxLonDelta + (lon2 - pred.lonBase)];
    System.out.println("relation=" + relation
        + " CROSSES=" + PointValues.Relation.CELL_CROSSES_QUERY.ordinal()
        + " INSIDE=" + PointValues.Relation.CELL_INSIDE_QUERY.ordinal()
        + " OUTSIDE=" + PointValues.Relation.CELL_OUTSIDE_QUERY.ordinal());
    System.out.println("bounds rect: minLat=" + poly.minLat);
    System.out.println("tree.contains=" + comp.contains(docLon, docLat));
  }
}

