import org.apache.lucene.index.IndexReader;
import org.apache.lucene.index.IndexWriter;
import org.apache.lucene.index.IndexWriterConfig;
import org.apache.lucene.index.SerialMergeScheduler;
import org.apache.lucene.search.IndexSearcher;
import org.apache.lucene.search.Query;
import org.apache.lucene.store.Directory;
import org.apache.lucene.tests.util.LuceneTestCase;
import org.apache.lucene.util.IOUtils;

/** Tests for the component2D predicate built from encoded points. */
public class TestNarrowPolygonNearPole extends LuceneTestCase {

  private static final String FIELD_NAME = "point";

  private static final double LAT0 = decodeLatitude(Integer.MAX_VALUE - 2);
  private static final double LON0 = decodeLongitude(Integer.MAX_VALUE - 2);

  public void testNarrowPolygonCloseToNorthPolePoint() throws Exception {
    Directory dir = newDirectory();
    IndexWriter w = new IndexWriter(dir, newIndexWriterConfig());
    Document doc = new org.apache.lucene.document.Document();
    doc.add(new LatLonPoint(FIELD_NAME, LAT0, LON0));
    w.addDocument(doc);
    w.commit();
    IndexReader reader = DirectoryReader.open(w);
    IndexSearcher s = newSearcher(reader);

    double minLat = decodeLatitude(Integer.MAX_VALUE - 3);
    double maxLat = decodeLatitude(Integer.MAX_VALUE);
    double minLon = decodeLongitude(Integer.MAX_VALUE - 3);
    double maxLon = decodeLongitude(Integer.MAX_VALUE);
    Query query =
        LatLonPoint.newPolygonQuery(
            FIELD_NAME,
            new Polygon(
                new double[] {minLat, minLat, maxLat, maxLat, minLat},
                new double[] {minLon, maxLon, maxLon, minLon, minLon}));
    assertEquals(1, s.count(query));
    IOUtils.close(w, reader, dir);
  }

  public void testNarrowPolygonCloseToNorthPoleDocValues() throws Exception {
    Directory dir = newDirectory();
    IndexWriter w = new IndexWriter(dir, newIndexWriterConfig());
    Document doc = new org.apache.lucene.document.Document();
    doc.add(new LatLonDocValuesField(FIELD_NAME, LAT0, LON0));
    w.addDocument(doc);
    w.commit();
    IndexReader reader = DirectoryReader.open(w);
    IndexSearcher s = newSearcher(reader);

    double minLat = decodeLatitude(Integer.MAX_VALUE - 3);
    double maxLat = decodeLatitude(Integer.MAX_VALUE);
    double minLon = decodeLongitude(Integer.MAX_VALUE - 3);
    double maxLon = decodeLongitude(Integer.MAX_VALUE);
    Query query =
        LatLonDocValuesField.newPolygonQuery(
            FIELD_NAME,
            new Polygon(
                new double[] {minLat, minLat, maxLat, maxLat, minLat},
                new double[] {minLon, maxLon, maxLon, minLon, minLon}));
    assertEquals(1, s.count(query));
    IOUtils.close(w, reader, dir);
  }
}

